    x_temp[i] = x[i] + 0.5 * h * k2[i];
}
std::vector<double> k3 = f(x_temp, t + 0.5 * h);

// Compute k4 = f(x + h*k3, t + h)
for (size_t i = 0; i < n; ++i) {
    x_temp[i] = x[i] + h * k3[i];
}
std::vector<double> k4 = f(x_temp, t + h);

// Compute the next state using weighted average
for (size_t i = 0; i < n; ++i) {
    next_x[i] = x[i] + h * (k1[i] + 2.0 * k2[i] + 2.0 * k3[i] + k4[i]) / 6.0;
}

return next_x;

